--
-- Name: generate_mission_code(); Type: FUNCTION; Schema: public; Owner: neondb_owner
--

CREATE FUNCTION public.generate_mission_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.mission_code :=
        'M-' ||
        TO_CHAR(CURRENT_DATE, 'YYYY') ||
        '-' ||
        LPAD(NEW.mission_id::TEXT, 6, '0');

    RETURN NEW;
END;
$$;


