--
-- Name: prevent_duplicate_daily_volunteer(); Type: FUNCTION; Schema: public; Owner: neondb_owner
--

CREATE FUNCTION public.prevent_duplicate_daily_volunteer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    open_mission BOOLEAN;
BEGIN
    SELECT is_open_mission
    INTO open_mission
    FROM missions
    WHERE mission_id = NEW.mission_id
    FOR UPDATE;

    IF open_mission = FALSE THEN

        IF EXISTS (
            SELECT 1
            FROM mission_participants
            WHERE mission_id = NEW.mission_id
              AND volunteer_id = NEW.volunteer_id
        ) THEN

            RAISE EXCEPTION
                'Volunteer % is already assigned to daily mission %',
                NEW.volunteer_id,
                NEW.mission_id
                USING ERRCODE = '23505';

        END IF;

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.prevent_duplicate_daily_volunteer() OWNER TO neondb_owner;

