    mission_id bigint NOT NULL,
    previous_status character varying(50) NOT NULL,
    new_status character varying(50) NOT NULL,
    action character varying(20) NOT NULL,
    action_by integer NOT NULL,
    action_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    reason text,
    CONSTRAINT mission_status_history_action_check CHECK (((action)::text = ANY (ARRAY[('submit'::character varying)::text, ('review'::character varying)::text, ('approve'::character varying)::text, ('complete'::character varying)::text, ('final_review'::character varying)::text, ('archive'::character varying)::text, ('return'::character varying)::text, ('cancel'::character varying)::text]))),
    CONSTRAINT mission_status_history_reason_check CHECK (((((action)::text = ANY (ARRAY[('return'::character varying)::text, ('cancel'::character varying)::text])) AND (reason IS NOT NULL) AND (btrim(reason) <> ''::text)) OR ((action)::text <> ALL (ARRAY[('return'::character varying)::text, ('cancel'::character varying)::text]))))
);


